/* Phone appearance and dimension views. No WebGL is loaded by this controller. */
(()=>{'use strict';const form=document.querySelector('[data-phone-size]');if(!form)return;
 const a=form.elements.a,b=form.elements.b,overlay=form.elements.overlay,folded=form.elements.folded,foldedOption=form.querySelector('[data-phone-folded-option]'),scale=form.querySelector('[data-phone-scale]'),output=form.querySelector('output'),models=form.querySelector('[data-phone-comparison]'),template=document.querySelector('[data-phone-view-templates]'),facts=form.querySelector('[data-phone-measurements]');let previous='';
 const core=p=>{const values=Object.fromEntries(Object.entries(p.fields).map(([key,f])=>[key,f.value]));if(folded.checked&&values.foldedHeight){values.height=values.foldedHeight;values.width=values.foldedWidth;values.depth=values.foldedDepth;}return values};
 const dimensionName=p=>p.name+(folded.checked&&p.fields.foldedHeight?.value?' (folded)':'');
 const modes=[...form.querySelectorAll('[data-phone-mode]')];
 function mode(value){for(const button of modes)button.setAttribute('aria-pressed',String(button.dataset.phoneMode===value));form.querySelector('[data-phone-design]').hidden=value!=='design';form.querySelector('[data-phone-size-view]').hidden=value!=='size';form.querySelector('[data-phone-mode-help]').textContent=value==='design'?'Open a 3D view, then drag to explore the phone.':'Compare body outlines at a shared scale.'}
 modes.forEach(button=>button.addEventListener('click',()=>mode(button.dataset.phoneMode)));
 fetch('/data/phones-v1.json').then(r=>{if(!r.ok)throw Error('Phone dimensions are temporarily unavailable.');return r.json()}).then(({phones})=>{
  function draw(){const pair=[a,b].map(select=>phones.find(p=>p.id===select.value));if(pair.some(p=>!p))return;foldedOption.hidden=!pair.some(p=>p.fields.foldedHeight?.value);if(foldedOption.hidden)folded.checked=false;const [first,second]=pair,[ca,cb]=pair.map(core),maxHeight=Math.max(ca.height,cb.height);scale.replaceChildren();
   for(const [i,p]of pair.entries()){const f=core(p),figure=document.createElement('figure'),svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),rect=document.createElementNS(svg.namespaceURI,'rect'),caption=document.createElement('figcaption');svg.setAttribute('viewBox',`0 0 ${f.width} ${maxHeight}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',`${p.name}, ${f.height} millimetres tall and ${f.width} millimetres wide`);svg.style.color=i===0?'var(--accent-ink)':'var(--phone-secondary)';rect.setAttribute('x','1');rect.setAttribute('y',String(maxHeight-f.height+1));rect.setAttribute('width',String(f.width-2));rect.setAttribute('height',String(f.height-2));rect.setAttribute('rx','7');rect.setAttribute('fill','currentColor');rect.setAttribute('fill-opacity','.08');rect.setAttribute('stroke','currentColor');rect.setAttribute('stroke-width','1.3');svg.append(rect);caption.textContent=dimensionName(p);figure.append(svg,caption);scale.append(figure)}scale.classList.toggle('overlay',overlay.checked);
   const selection=pair.map(p=>p.id).join(',');if(selection!==previous&&models&&template){const grid=document.createElement('section');grid.className='phone-comparison-views';grid.setAttribute('aria-label','Phone viewing angles');for(const p of pair){const card=[...template.content.querySelectorAll('[data-phone-preview]')].find(el=>el.dataset.phonePreview===p.id)?.closest('article');if(card)grid.append(card.cloneNode(true))}models.replaceChildren(grid);previous=selection;document.dispatchEvent(new Event('pcp:phone-selection'))}
   facts.replaceChildren();const table=document.createElement('table');table.className='phone-dimensions-table';const head=document.createElement('thead'),row=document.createElement('tr');for(const label of ['Dimension',dimensionName(first),dimensionName(second)]){const th=document.createElement('th');th.scope='col';th.textContent=label;row.append(th)}head.append(row);table.append(head);const body=document.createElement('tbody');for(const [key,label,unit]of [['height','Height','mm'],['width','Width','mm'],['depth','Thickness','mm'],['weight','Weight','g']]){const tr=document.createElement('tr'),th=document.createElement('th');th.scope='row';th.textContent=label;tr.append(th);for(const c of [ca,cb]){const td=document.createElement('td');td.textContent=Number.isFinite(c[key])?c[key]+' '+unit:'Not verified';tr.append(td)}body.append(tr)}table.append(body);facts.append(table);
   const pieces=[];for(const [key,label,opposite,unit]of [['height','taller','shorter','mm'],['width','wider','narrower','mm'],['depth','thicker','thinner','mm'],['weight','heavier','lighter','g']]){if(!Number.isFinite(ca[key])||!Number.isFinite(cb[key]))continue;const n=cb[key]-ca[key];if(n!==0)pieces.push(`${Number(Math.abs(n).toFixed(2))} ${unit} ${n>0?label:opposite}`)}output.textContent=pieces.length?`${second.name} is ${pieces.join(', ')} than ${first.name}${folded.checked?' using folded dimensions where available':''}.`:'The recorded dimensions match.';for(const td of facts.querySelectorAll('td'))if(td.textContent.startsWith('null '))td.textContent='Not verified';
  }
  a.addEventListener('change',draw);b.addEventListener('change',draw);overlay.addEventListener('change',draw);folded.addEventListener('change',draw);form.querySelector('[data-phone-swap]').addEventListener('click',()=>{[a.value,b.value]=[b.value,a.value];a.dispatchEvent(new Event('change',{bubbles:true}));b.dispatchEvent(new Event('change',{bubbles:true}))});draw();
 }).catch(error=>{output.textContent=error.message});
})();

